def copiar_indices_para_o_nucleo(apps, schema_editor):
    """A série do Orçamento vai para a série única do `nucleo` antes de a
    tabela sumir (decisão do dono, 10/10/2026). Código em minúsculo; se o
    `nucleo` já tem o índice, completa o que falta em cada competência —
    número-índice onde só havia variação, e vice-versa — sem sobrescrever."""
    Velho = apps.get_model("moduloorcamento", "IndiceEconomico")
    VelhoValor = apps.get_model("moduloorcamento", "ValorIndice")
    Novo = apps.get_model("nucleo", "IndiceEconomico")
    NovoValor = apps.get_model("nucleo", "ValorIndice")
    for velho in Velho.objects.all():
        novo, _ = Novo.objects.get_or_create(
            codigo=velho.codigo.strip().lower()[:20],
            defaults={"nome": velho.nome, "fonte": velho.fonte, "uf": velho.uf, "ativo": velho.ativo},
        )
        existentes = {v.competencia: v for v in NovoValor.objects.filter(indice=novo)}
        for valor in VelhoValor.objects.filter(indice=velho).order_by("competencia"):
            atual = existentes.get(valor.competencia)
            if atual is None:
                NovoValor.objects.create(
                    indice=novo, competencia=valor.competencia,
                    numero_indice=valor.numero_indice, variacao_percentual=valor.variacao_percentual,
                )
                continue
            mudou = False
            if atual.numero_indice is None and valor.numero_indice is not None:
                atual.numero_indice, mudou = valor.numero_indice, True
            if atual.variacao_percentual is None and valor.variacao_percentual is not None:
                atual.variacao_percentual, mudou = valor.variacao_percentual, True
            if mudou:
                atual.save(update_fields=["numero_indice", "variacao_percentual"])


